def cmp_semver(a, b):
    def parse(v):
        v = v.split('+')[0]
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core, pre_ids = v, []
        major, minor, patch = map(int, core.split('.'))
        return (major, minor, patch), pre_ids

    (ma, mi, pa), pre_a = parse(a)
    (mb, mi2, pb), pre_b = parse(b)

    if (ma, mi, pa) != (mb, mi2, pb):
        return -1 if (ma, mi, pa) < (mb, mi2, pb) else 1

    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for ida, idb in zip(pre_a, pre_b):
        a_num = ida.isdigit()
        b_num = idb.isdigit()
        if a_num and b_num:
            na, nb = int(ida), int(idb)
            if na != nb:
                return -1 if na < nb else 1
        elif a_num:
            return -1
        elif b_num:
            return 1
        else:
            if ida != idb:
                return -1 if ida < idb else 1
    if len(pre_a) != len(pre_b):
        return -1 if len(pre_a) < len(pre_b) else 1
    return 0
