def parse_range(header, size):
    if not isinstance(header, str) or not header:
        return None
    header = header.strip()
    if not header.lower().startswith('bytes='):
        return None
    ranges_str = header[6:]  # strip "bytes="
    if not ranges_str:
        return None
    result = []
    for part in ranges_str.split(','):
        part = part.strip()
        if not part:
            return None
        # suffix-byte-range-spec
        if part.startswith('-'):
            try:
                suffix_len = int(part[1:])
            except ValueError:
                return None
            if suffix_len <= 0:
                return None
            start = max(0, size - suffix_len)
            end = size - 1
        else:
            if '-' not in part:
                return None
            start_str, end_str = part.split('-', 1)
            # start must be present
            if start_str == '':
                return None
            try:
                start = int(start_str)
            except ValueError:
                return None
            if start < 0:
                return None
            # end may be empty -> open-ended
            if end_str == '':
                end = size - 1
            else:
                try:
                    end = int(end_str)
                except ValueError:
                    return None
                if end < 0:
                    return None
            # unsatisfiable checks
            if start >= size:
                continue
            if end >= size:
                end = size - 1
            if start > end:
                continue
            result.append((start, end))
    return result if result else None
