import difflib
from typing import List

def unified_diff(a: List[str], b: List[str], context: int = 3) -> List[str]:
    if a == b:
        return []
    matcher = difflib.SequenceMatcher(None, a, b, autojunk=False)
    opcodes = matcher.get_opcodes()
    changes = [(i1, i2, j1, j2) for tag, i1, i2, j1, j2 in opcodes if tag != 'equal']
    if not changes:
        return []
    hunks: List[List[int]] = []
    for a_start, a_end, b_start, b_end in changes:
        a0 = max(0, a_start - context)
        a1 = min(len(a), a_end + context)
        b0 = max(0, b_start - context)
        b1 = min(len(b), b_end + context)
        if not hunks:
            hunks.append([a0, a1, b0, b1])
        else:
            last = hunks[-1]
            if a0 <= last[1] or b0 <= last[3]:
                last[0] = min(last[0], a0)
                last[1] = max(last[1], a1)
                last[2] = min(last[2], b0)
                last[3] = max(last[3], b1)
            else:
                hunks.append([a0, a1, b0, b1])
    result: List[str] = []
    for a0, a1, b0, b1 in hunks:
        result.append(f'@@ -{a0+1},{a1-a0} +{b0+1},{b1-b0} @@')
        for tag, i1, i2, j1, j2 in opcodes:
            a_seg_start = max(i1, a0)
            a_seg_end = min(i2, a1)
            b_seg_start = max(j1, b0)
            b_seg_end = min(j2, b1)
            if a_seg_start >= a_seg_end and b_seg_start >= b_seg_end:
                continue
            if tag == 'equal':
                for k in range(a_seg_start, a_seg_end):
                    result.append(' ' + a[k])
            elif tag == 'delete':
                for k in range(a_seg_start, a_seg_end):
                    result.append('-' + a[k])
            elif tag == 'insert':
                for k in range(b_seg_start, b_seg_end):
                    result.append('+' + b[k])
            elif tag == 'replace':
                for k in range(a_seg_start, a_seg_end):
                    result.append('-' + a[k])
                for k in range(b_seg_start, b_seg_end):
                    result.append('+' + b[k])
    return result
