from datetime import datetime, timedelta

def next_fire(expr, after):
    """
    Return the earliest datetime strictly after `after` when the 5-field cron
    expression `expr` fires, with seconds and microseconds set to zero.
    """
    if not isinstance(after, datetime):
        raise ValueError("after must be a datetime instance")

    # ------------------------------------------------------------------
    # Helper: parse a single cron field into a set of allowed integers
    # ------------------------------------------------------------------
    def parse_field(field_str, min_val, max_val):
        if not field_str:
            raise ValueError("empty field")
        values = set()
        for part in field_str.split(','):
            if '/' in part:
                base, step_str = part.split('/')
                if step_str == '' or not step_str.isdigit():
                    raise ValueError(f"invalid step in '{part}'")
                step = int(step_str)
                if step <= 0:
                    raise ValueError(f"step must be >0 in '{part}'")
            else:
                base = part
                step = 1

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                low_high = base.split('-')
                if len(low_high) != 2:
                    raise ValueError(f"invalid range in '{part}'")
                try:
                    low = int(low_high[0])
                    high = int(low_high[1])
                except ValueError:
                    raise ValueError(f"non‑numeric range in '{part}'")
                if low > high:
                    raise ValueError(f"invalid range bounds in '{part}'")
                start, end = low, high
            else:
                try:
                    val = int(base)
                except ValueError:
                    raise ValueError(f"non‑numeric value in '{part}'")
                start = end = val

            if start < min_val or end > max_val:
                raise ValueError(f"value out of range in '{part}'")
            for v in range(start, end + 1, step):
                if v < min_val or v > max_val:
                    raise ValueError(f"stepped value out of range in '{part}'")
                values.add(v)
        return values

    # ------------------------------------------------------------------
    # Split expression into its five fields
    # ------------------------------------------------------------------
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("expression must have exactly five fields")
    minute_expr, hour_expr, dom_expr, month_expr, dow_expr = fields

    # ------------------------------------------------------------------
    # Parse each field, also remember if it was exactly '*'
    # ------------------------------------------------------------------
    minute_set = parse_field(minute_expr, 0, 59)
    hour_set   = parse_field(hour_expr,   0, 23)
    dom_set    = parse_field(dom_expr,    1, 31)
    month_set  = parse_field(month_expr,  1, 12)
    dow_set    = parse_field(dow_expr,    0, 6)

    dom_is_star = (dom_expr.strip() == '*')
    dow_is_star = (dow_expr.strip() == '*')

    # ------------------------------------------------------------------
    # Test whether a given datetime matches the cron expression
    # ------------------------------------------------------------------
    def matches(dt):
        if dt.minute not in minute_set:
            return False
        if dt.hour not in hour_set:
            return False
        if dt.month not in month_set:
            return False

        # day-of-month / day-of-week logic
        if dom_is_star and dow_is_star:
            return True
        if dom_is_star:
            dow = (dt.weekday() + 1) % 7   # convert Monday=0..Sunday=6 to 0=Sunday..6=Saturday
            return dow in dow_set
        if dow_is_star:
            return dt.day in dom_set
        # both restricted -> OR
        return (dt.day in dom_set) or (((dt.weekday() + 1) % 7) in dow_set)

    # ------------------------------------------------------------------
    # Start searching from the next minute after `after`
    # ------------------------------------------------------------------
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Safety limit: avoid infinite loops in case of logic errors
    max_iterations = 10 * 366 * 24 * 60  # roughly ten years
    for _ in range(max_iterations):
        if matches(current):
            return current
        current += timedelta(minutes=1)

    raise ValueError("No matching time found within a reasonable range")
