import heapq
from collections import defaultdict

def window_medians(a, k):
    if k > len(a) or k == 0:
        return []

    small = []   # max heap (store negatives)
    large = []   # min heap
    delayed = defaultdict(int)
    small_size = 0
    large_size = 0
    res = []

    def prune(heap, is_small):
        while heap:
            val = -heap[0] if is_small else heap[0]
            if delayed.get(val, 0):
                heapq.heappop(heap)
                delayed[val] -= 1
                if delayed[val] == 0:
                    del delayed[val]
            else:
                break

    def rebalance():
        if small_size > large_size + 1:
            heapq.heappush(large, -heapq.heappop(small))
            small_size -= 1
            large_size += 1
            prune(small, True)
        elif small_size < large_size:
            heapq.heappush(small, -heapq.heappop(large))
            large_size -= 1
            small_size += 1
            prune(large, False)

    # build first window
    for i in range(k):
        x = a[i]
        if not small or x <= -small[0]:
            heapq.heappush(small, -x)
            small_size += 1
        else:
            heapq.heappush(large, x)
            large_size += 1
        rebalance()

    def median():
        if k & 1:
            return float(-small[0])
        return (-small[0] + large[0]) / 2.0

    res.append(median())

    # slide the window
    for i in range(k, len(a)):
        out_val = a[i - k]
        in_val = a[i]

        # schedule removal of outgoing element
        delayed[out_val] += 1
        if out_val <= -small[0]:
            small_size -= 1
            if out_val == -small[0]:
                prune(small, True)
        else:
            large_size -= 1
            if large and out_val == large[0]:
                prune(large, False)

        # insert incoming element
        if small and in_val <= -small[0]:
            heapq.heappush(small, -in_val)
            small_size += 1
        else:
            heapq.heappush(large, in_val)
            large_size += 1

        rebalance()
        prune(small, True)
        prune(large, False)

        res.append(median())

