            prune(large, False)

    # build first window
    for i in range(k):
        x = a[i]
        if not small or x <= -small[0]:
            heapq.heappush(small, -x)
            small_size += 1
        else:
            heapq.heappush(large, x)
            large_size += 1
        rebalance()

    def median():
        if k & 1:
            return float(-small[0])
        return (-small[0] + large[0]) / 2.0

    res.append(median())

    # slide the window
    for i in range(k, len(a)):
        out_val = a[i - k]
        in_val = a[i]

        # schedule removal of outgoing element
        delayed[out_val] += 1
        if out_val <= -small[0]:
            small_size -= 1
            if out_val == -small[0]:
                prune(small, True)
        else:
            large_size -= 1
            if large and out_val == large[0]:
                prune(large, False)

        # insert incoming element
        if small and in_val <= -small[0]:
            heapq.heappush(small, -in_val)
            small_size += 1
        else:
            heapq.heappush(large, in_val)
            large_size += 1

        rebalance()
        prune(small, True)
        prune(large, False)

