class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.changes = []          # stack of (child, parent_before, size_parent_before)
        self._count = n            # number of current components

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        # union by size: ensure ra has larger (or equal) size
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        # record state to allow rollback
        self.changes.append((rb, ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self._count -= 1
        return True

    def snapshot(self):
        return len(self.changes)

    def rollback(self, token):
        while len(self.changes) > token:
            rb, ra, size_ra_before = self.changes.pop()
            self.parent[rb] = rb
            self.size[ra] = size_ra_before
            self._count += 1

    def components(self):
        return self._count
