class WildcardTrie:
    class _Node:
        __slots__ = ("children", "count")
        def __init__(self):
            self.children = {}
            self.count = 0

    def __init__(self):
        self._root = self._Node()

    def add(self, word: str) -> None:
        node = self._root
        for ch in word:
            node = node.children.setdefault(ch, self._Node())
        node.count += 1

    def remove(self, word: str) -> bool:
        node = self._root
        path = []  # list of (parent_node, char)
        for ch in word:
            if ch not in node.children:
                return False
            path.append((node, ch))
            node = node.children[ch]
        if node.count == 0:
            return False
        node.count -= 1
        # prune unnecessary nodes
        if node.count == 0 and not node.children:
            for parent, ch in reversed(path):
                child = parent.children[ch]
                if child.count == 0 and not child.children:
                    del parent.children[ch]
                else:
                    break
        return True

    def search(self, pattern: str):
        results = []

        def dfs(node: self._Node, i: int, prefix: str):
            if i == len(pattern):
                if node.count > 0:
                    results.append(prefix)
                return
            ch = pattern[i]
            if ch == '.':
                for c, child in node.children.items():
                    dfs(child, i + 1, prefix + c)
            else:
                child = node.children.get(ch)
                if child:
                    dfs(child, i + 1, prefix + ch)

        dfs(self._root, 0, "")
        return sorted(results)
