def subtract(base, cuts):
    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_intervals = sorted(intervals, key=lambda x: x[0])
        merged = []
        cur_start, cur_end = sorted_intervals[0]
        for s, e in sorted_intervals[1:]:
            if s <= cur_end:
                if e > cur_end:
                    cur_end = e
            else:
                merged.append([cur_start, cur_end])
                cur_start, cur_end = s, e
        merged.append([cur_start, cur_end])
        return merged

    base_union = merge_intervals(base)
    cuts_union = merge_intervals(cuts)
    result = []
    i = 0
    n = len(cuts_union)
    for bs, be in base_union:
        cur = bs
        while i < n and cuts_union[i][1] <= cur:
            i += 1
        j = i
        while j < n and cuts_union[j][0] < be:
            cs, ce = cuts_union[j]
            if cs > cur:
                result.append([cur, cs])
            cur = max(cur, ce)
            if cur >= be:
                break
            j += 1
        if cur < be:
            result.append([cur, be])
        i = j
    return result
