def deep_copy(obj, _memo=None):
    if _memo is None:
        _memo = {}
    obj_id = id(obj)
    if obj_id in _memo:
        return _memo[obj_id]

    # immutable scalars
    if isinstance(obj, (int, float, bool, str, type(None))):
        _memo[obj_id] = obj
        return obj

    if isinstance(obj, dict):
        copy = {}
        _memo[obj_id] = copy
        for k, v in obj.items():
            copy[deep_copy(k, _memo)] = deep_copy(v, _memo)
        return copy

    if isinstance(obj, list):
        copy = []
        _memo[obj_id] = copy
        for item in obj:
            copy.append(deep_copy(item, _memo))
        return copy

    if isinstance(obj, set):
        copy = set()
        _memo[obj_id] = copy
        for item in obj:
            copy.add(deep_copy(item, _memo))
        return copy

    if isinstance(obj, tuple):
        # tuples are immutable; we assume they do not participate in cycles
        copy = tuple(deep_copy(item, _memo) for item in obj)
        _memo[obj_id] = copy
        return copy

    # fallback (should not be reached for allowed types)
    return obj

