def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Base must be at least 2")
    if n == 0:
        return alphabet[0]
    sign = '-' if n < 0 else ''
    n = abs(n)
    digits = []
    while n:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])
    return sign + ''.join(reversed(digits))


def from_base(s, alphabet):
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Base must be at least 2")
    if not s:
        raise ValueError("Empty string")
    sign = 1
    if s[0] == '-':
        sign = -1
        s = s[1:]
    if not s:
        raise ValueError("String contains only a sign")
    value = 0
    for ch in s:
        if ch not in alphabet:
            raise ValueError(f"Invalid character {ch!r} for given alphabet")
        value = value * base + alphabet.index(ch)
    return sign * value
