import heapq

def shortest_path(graph, src, dst):
    heap = []
    heapq.heappush(heap, (0, 0, [src], src))   # (cost, edges, path, node)
    best = {}                                   # node -> (cost, edges, path)

    while heap:
        cost, edges, path, u = heapq.heappop(heap)

        # Skip if we already have a better record for u
        if u in best:
            bc, be, bp = best[u]
            if cost > bc or (cost == bc and edges > be) or (cost == bc and edges == be and path > bp):
                continue

        best[u] = (cost, edges, path)

        if u == dst:
            return (cost, path)

        for v, w in graph.get(u, []):
            ncost = cost + w
            nedges = edges + 1
            npath = path + [v]          # create new path list
            heapq.heappush(heap, (ncost, nedges, npath, v))

    return (None, [])
