import heapq

def topo_lex(graph):
    # Collect all nodes (keys and any successors)
    nodes = set()
    indeg = {}
    for u, succs in graph.items():
        nodes.add(u)
        for v in succs:
            nodes.add(v)
            indeg[v] = indeg.get(v, 0) + 1
    for n in nodes:
        indeg.setdefault(n, 0)

    # Initialize heap with zero‑indegree nodes
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in graph.get(u, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    return order if len(order) == len(nodes) else None
