function createStore(reducer, initial) {
  let state = initial;
  const listeners = []; // each element: { fn, removed: false }
  let isReducing = false;

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (isReducing) {
      throw new Error('Reducers may not dispatch actions.');
    }
    try {
      isReducing = true;
      state = reducer(state, action);
    } finally {
      isReducing = false;
    }
    const snapshot = listeners.slice();
    for (let i = 0; i < snapshot.length; i++) {
      const wrapper = snapshot[i];
      if (!wrapper.removed) {
        wrapper.fn();
      }
    }
    return action;
  }

  function subscribe(listener) {
    if (typeof listener !== 'function') {
      throw new Error('Listener must be a function.');
    }
    const wrapper = { fn: listener, removed: false };
    listeners.push(wrapper);
    return function unsubscribe() {
      if (wrapper.removed) return;
      wrapper.removed = true;
      const idx = listeners.indexOf(wrapper);
      if (idx >= 0) {
        listeners.splice(idx, 1);
      }
    };
  }

  return { getState, dispatch, subscribe };
}

module.exports = createStore;

