function toposortTasks(tasks) {
  const taskNames = Object.keys(tasks);
  const indegree = {};
  const graph = {};
  const depsMap = {};

  for (const name of taskNames) {
    const { deps } = tasks[name];
    depsMap[name] = deps;
    indegree[name] = 0;
    graph[name] = [];
  }

  for (const name of taskNames) {
    for (const dep of depsMap[name]) {
      if (!tasks.hasOwnProperty(dep)) {
        throw new Error(`Unknown dependency: ${dep}`);
      }
      graph[dep].push(name);
      indegree[name]++;
    }
  }

  // Cycle detection (Kahn's algorithm)
  const zeroIndegree = taskNames.filter(n => indegree[n] === 0);
  const topo = [];
  const indegCopy = { ...indegree };
  let queue = [...zeroIndegree];
  while (queue.length) {
    const n = queue.shift();
    topo.push(n);
    for (const dependent of graph[n]) {
      indegCopy[dependent]--;
      if (indegCopy[dependent] === 0) queue.push(dependent);
    }
  }
  if (topo.length !== taskNames.length) {
    throw new Error('Dependency cycle detected');
  }

  const results = {};
  const indegreeExec = { ...indegree };
  let ready = [...zeroIndegree];
  let overallError = null;

  while (ready.length > 0) {
    const level = ready.slice();
    ready = [];

    const levelPromises = level.map(name => {
      const depsObj = {};
      for (const dep of depsMap[name]) {
        depsObj[dep] = results[dep];
      }
      return tasks[name].run(depsObj).catch(err => {
        if (overallError === null) overallError = err;
        throw err;
      });
    });

    const settled = await Promise.allSettled(levelPromises);
    for (let i = 0; i < level.length; i++) {
      const name = level[i];
      const outcome = settled[i];
      if (outcome.status === 'fulfilled') {
        results[name] = outcome.value;
        for (const dependent of graph[name]) {
          indegreeExec[dependent]--;
          if (indegreeExec[dependent] === 0) ready.push(dependent);
        }
      }
      // rejected tasks: do not propagate to dependents
    }
  }

  if (overallError !== null) {
    throw overallError;
  }
  return results;
}

